function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      let comparisonResult = null;
      if (compareWithHistoricalData) {
        try {
          comparisonResult = compareWithHistoricalData(validProductData, startDate, endDate);
        } catch (error) {
          // 代替比較データを探す
          if (findAlternativeComparisonData) {
            comparisonResult = findAlternativeComparisonData(validProductData, startDate, endDate);
          }
        }
      }

      return {
        salesData: validProductData,
        weatherData,
        eventData,
        seasonalData,
        correlations: correlationResults,
        comparison: comparisonResult
      };

    } catch (error) {
      showError('需要予測データの取得に失敗しました: ' + error.message);
      return null;
    }
  }

  // 発注データを読み込み
  async function loadOrderData() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!validateDateRange()) return;

      const orders = await window.aivicApi.list(tables[ORDER_TABLE], {
        startDate,
        endDate,
        storeId
      });

      currentProducts = orders || [];
      updateOrderTable();

    } catch (error) {
      showError('発注データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 発注テーブルを更新
  function updateOrderTable() {
    const tbody = container.querySelector('#order-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    currentProducts.forEach((order, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><input type="checkbox" data-index="${index}" /></td>
        <td>${order.productName || ''}</td>
        <td>${order.currentStock || 0}</td>
        <td>${order.forecastDemand || 0}</td>
        <td><input type="number" value="${order.orderQuantity || 0}" data-index="${index}" class="order-quantity" /></td>
        <td>${order.orderDate || ''}</td>
        <td>${order.status || ''}</td>
      `;
      tbody.appendChild(row);
    });

    // チェックボックスのイベントリスナー
    tbody.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
      checkbox.addEventListener('change', updateSelectedOrders);
    });

    // 発注数量のイベントリスナー
    tbody.querySelectorAll('.order-quantity').forEach(input => {
      input.addEventListener('change', (e) => {
        const index = parseInt(e.target.dataset.index);
        if (currentProducts[index]) {
          currentProducts[index].orderQuantity = parseInt(e.target.value) || 0;
        }
      });
    });
  }

  // 選択された発注を更新
  function updateSelectedOrders() {
    selectedOrders = [];
    container.querySelectorAll('#order-table input[type="checkbox"]:checked').forEach(checkbox => {
      const index = parseInt(checkbox.dataset.index);
      if (currentProducts[index]) {
        selectedOrders.push(currentProducts[index]);
      }
    });
  }

  // 発注を実行
  async function executeOrder() {
    try {
      if (selectedOrders.length === 0) {
        showError('発注する商品を選択してください');
        return;
      }

      for (const order of selectedOrders) {
        await window.aivicApi.save(tables[ORDER_TABLE], {
          ...order,
          status: '発注済み',
          orderDate: new Date().toISOString().split('T')[0]
        });
      }

      showSuccess(`${selectedOrders.length}件の発注を実行しました`);
      await loadOrderData();

    } catch (error) {
      showError('発注の実行に失敗しました: ' + error.message);
    }
  }

  // 発注をキャンセル
  async function cancelOrder() {
    try {
      if (selectedOrders.length === 0) {
        showError('キャンセルする発注を選択してください');
        return;
      }

      for (const order of selectedOrders) {
        if (order.id) {
          await window.aivicApi.update(tables[ORDER_TABLE], order.id, {
            ...order,
            status: 'キャンセル'
          });
        }
      }

      showSuccess(`${selectedOrders.length}件の発注をキャンセルしました`);
      await loadOrderData();

    } catch (error) {
      showError('発注のキャンセルに失敗しました: ' + error.message);
    }
  }

  // 需要予測を実行
  async function executeForecast() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!validateDateRange()) return;

      if (!startDate || !endDate) {
        showError('期間を指定してください');
        return;
      }

      // 各商品について需要予測を実行
      const forecastResults = [];

      for (const product of currentProducts) {
        const forecast = await getDemandForecast(product.productId, storeId, startDate, endDate);
        if (forecast) {
          forecastResults.push({
            productId: product.productId,
            productName: product.productName,
            forecastDemand: forecast.salesData.reduce((sum, data) => sum + (data.quantity || 0), 0),
            correlations: forecast.correlations,
            comparison: forecast.comparison
          });
        }
      }

      // 予測結果をテーブルに反映
      currentProducts.forEach(product => {
        const forecast = forecastResults.find(f => f.productId === product.productId);
        if (forecast) {
          product.forecastDemand = forecast.forecastDemand;
          // 安全在庫を考慮した発注数量を計算
          const safetyStock = Math.ceil(forecast.forecastDemand * 0.2); // 20%の安全在庫
          product.orderQuantity = Math.max(0, forecast.forecastDemand + safetyStock - (product.currentStock || 0));
        }
      });

      updateOrderTable();
      showSuccess('需要予測が完了しました');

    } catch (error) {
      showError('需要予測の実行に失敗しました: ' + error.message);
    }
  }

  // 店舗データを読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(tables[STORES_TABLE]);
      const storeSelect = container.querySelector('#store-select');

      if (storeSelect && stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択</option>';
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.name;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('店舗データの読み込みに失敗しました: ' + error.message);
    }
  }

  // イベントリスナーを設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#search-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', loadOrderData);
    }

    // 需要予測ボタン
    const forecastBtn = container.querySelector('#forecast-btn');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 発注実行ボタン
    const orderBtn = container.querySelector('#order-btn');
    if (orderBtn) {
      orderBtn.addEventListener('click', executeOrder);
    }

    // 発注キャンセルボタン
    const cancelBtn = container.querySelector('#cancel-btn');
    if (cancelBtn) {
      cancelBtn.addEventListener('click', cancelOrder);
    }

    // 日付変更時のバリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });

    // 店舗選択変更時
    const storeSelect = container.querySelector('#store-select');
    if (storeSelect) {
      storeSelect.addEventListener('change', () => {
        if (storeSelect.value) {
          loadOrderData();
        }
      });
    }
  }

  // 初期化
  async function initialize() {
    try {
      await loadStores();
      setupEventListeners();

      // デフォルト日付を設定
      const today = new Date();
      const startDate = new Date(today.getFullYear(), today.getMonth(), 1);
      const endDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);

      const startInput = container.querySelector('#date-start');
      const endInput = container.querySelector('#date-end');

      if (startInput) startInput.value = startDate.toISOString().split('T')[0];
      if (endInput) endInput.value = endDate.toISOString().split('T')[0];

    } catch (error) {
      showError('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
